def mru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Most Recently Used (MRU)
    algorithm.
    """
    def decorator(func):
        cache = {}
        def wrapper(*args, **kwargs):
            # Generate the key from the function arguments
            key = args + tuple(kwargs.items())
            if key in cache:
                # If the key is already in the cache, return the cached result
                return cache[key]
            else:
                # If the key is not in the cache, call the function and store the result
                result = func(*args, **kwargs)
                cache[key] = result
                # If the cache is full, remove the least recently used key
                if len(cache) > maxsize:
                    cache.popitem(last=False)
                return result
        return wrapper
    return decorator

