def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    new_args = []
    for arg in args:
        if isinstance(arg, And):
            if any(x in arg.values for x in new_args):
                new_args.append(arg)
        elif isinstance(arg, Or):
            if any(x not in arg.values for x in new_args):
                new_args.append(arg)
        else:
            new_args.append(arg)
    return new_args

