def render(pieces, style):
    """Render the given version pieces into the requested style."""
    if pieces is None:
        return None

    if not isinstance(pieces, (list, tuple)):
        raise ValueError("pieces must be a list or a tuple")

    if style not in ("text", "markdown", "latex"):
        raise ValueError("style must be one of: text, markdown, or latex")

    rendered = []
    for piece in pieces:
        if style == "text":
            rendered.append(str(piece))
        elif style == "markdown":
            rendered.append("**" + str(piece) + "**")
        elif style == "latex":
            rendered.append(r"\emph{" + str(piece) + "}")

    return " ".join(rendered)

