def deep_merge_nodes(nodes):
    result = []
    for node in nodes:
        key, value = node
        # Check if there's already a mapping for this key in the result
        existing_value = next((v for k, v in result if k == key), None)
        if existing_value:
            # If there is, merge the values if they're both MappingNodes
            if isinstance(value, MappingNode) and isinstance(existing_value, MappingNode):
                result.remove(existing_value)
                result.append((key, deep_merge_nodes((existing_value, value))))
            else:
                # Otherwise, the last value wins
                result.append(node)
        else:
            # If there isn't a mapping for this key, add it to the result
            result.append(node)
    return result

